import math

def is_power_of_5(num):
    if num <= 0:
        return False
    if num == 1:
        return True
    while num % 5 == 0:
        num //= 5
    return num == 1

results = {}
for n in range(3, 21):
    value = (2**n) - 3
    is_p5 = is_power_of_5(value)
    results[n] = (value, is_p5)

print("n | 2^n - 3 | Is Power of 5")
print("--------------------------------")
for n, (value, is_p5) in results.items():
    print(f"{n} | {value} | {is_p5}")

# Identify successful cases for pattern analysis
successful_n = [n for n, (value, is_p5) in results.items() if is_p5]
print("\nSuccessful n values:", successful_n)

def is_odd_power_of_5(X):
    if X <= 0:
        return False, None

    k = 0
    temp_X = X
    while temp_X > 1:
        if temp_X % 5 != 0:
            return False, None
        temp_X //= 5
        k += 1

    # Check if the exponent k is odd
    if k % 2 != 0:
        return True, k
    else:
        return False, k

N_values = [9, 11, 13, 15]
results = {}

for n in N_values:
    value = (2**n) - 3
    is_power_of_5, k = is_odd_power_of_5(value)

    results[n] = {
        "Value": value,
        "Is Power of 5 (Odd k)": is_power_of_5,
        "Exponent k": k
    }

# Print results in a readable format
print("--- Results for n=9, 11, 13, 15 ---")
for n, data in results.items():
    print(f"\nn = {n}:")
    print(f"  2^n - 3 = {data['Value']}")
    print(f"  Is it an odd power of 5? {data['Is Power of 5 (Odd k)']}")
    if data['Is Power of 5 (Odd k)']:
        print(f"  Exponent k = {data['Exponent k']}")

def power_mod(base, exponent, modulus):
    return pow(base, exponent, modulus)

# Check 2^n mod 25 for n=1 to 20
results = {}
for n in range(1, 21):
    results[n] = power_mod(2, n, 25)

print("Powers of 2 modulo 25:")
for n, val in results.items():
    print(f"2^{n} mod 25 = {val}")

# Check for 2^n = 3 mod 25
solution_n = [n for n, val in results.items() if val == 3]
print(f"\nSolutions for 2^n = 3 mod 25 (up to 20): {solution_n}")

def check_power_of_5(number):
    if number <= 0:
        return False
    while number % 5 == 0:
        number //= 5
    return number == 1

n_values = [3, 7]
results = {}
for n in n_values:
    result = 2**n - 3
    is_power = check_power_of_5(result)
    results[n] = (result, is_power)

for n, (result, is_power) in results.items():
    print(f"n={n}: 2^n - 3 = {result}. Is it a power of 5? {is_power}")

